// The two typefaces every video uses, embedded in the page (no font
// requests leave the device). Subsets are generated by tools/subset_fonts.py
// from the originals in reference/python/fonts (Poppins: SIL OFL 1.1,
// Roboto: Apache 2.0; see FONT_LICENSES.txt there).

import { FONT_FACES } from './fontData.js';

let loading = null;

function b64ToBytes(b64) {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

/** Register Poppins and Roboto with the document (once). */
export function loadFonts() {
  if (loading) return loading;
  loading = (async () => {
    if (typeof FontFace === 'undefined' || typeof document === 'undefined') return false;
    const faces = FONT_FACES.map((f) => new FontFace(f.family, b64ToBytes(f.data), { weight: String(f.weight), style: 'normal' }));
    await Promise.all(faces.map((f) => f.load()));
    for (const f of faces) document.fonts.add(f);
    return true;
  })();
  return loading;
}
